// Uma classe abstrata mistura contrato com implementação, mas não pode ser instanciada.
abstract class FormaBase {
  abstract area(): number;

  descrever(): string {
    return `Esta forma tem área ${this.area()}`;
  }
}

class Quadrado extends FormaBase {
  constructor(private lado: number) {
    super();
  }

  area(): number {
    return this.lado * this.lado;
  }
}

const quadrado = new Quadrado(3);
console.log(quadrado.descrever());
// Esta forma tem área 9

// @ts-expect-error FormaBase é abstract: não pode ser instanciada diretamente
const generica = new FormaBase();

abstract class Sensor {
  abstract readonly unidade: string;
  abstract ler(): number;

  mostrar(): string {
    return `${this.ler()} ${this.unidade}`;
  }
}

class Termometro extends Sensor {
  readonly unidade = "C";

  ler(): number {
    return 21.5;
  }
}

console.log(new Termometro().mostrar());
// 21.5 C

// @ts-expect-error Higrometro não implementa o método abstrato ler
class Higrometro extends Sensor {
  readonly unidade = "%";
}

interface Formatador {
  formatar(valor: number): string;
}

class FormatadorSemTipo implements Formatador {
  // @ts-expect-error o parâmetro 'valor' fica implicitamente 'any': implements não o tipa
  formatar(valor) {
    return valor.toFixed(2);
  }
}

class FormatadorCorreto implements Formatador {
  formatar(valor: number): string {
    return valor.toFixed(2);
  }
}

console.log(new FormatadorCorreto().formatar(3.14159));
// 3.14

class FormatadorComRetornoErrado implements Formatador {
  // @ts-expect-error o retorno é 'number', mas Formatador exige 'string'
  formatar(valor: number) {
    return valor * 2;
  }
}

interface ComNome {
  nome: string;
}

abstract class Base {
  contador = 0;

  incrementar(): void {
    this.contador++;
  }
}

class Filha extends Base implements ComNome {
  nome = "filha";
}

const f = new Filha();
f.incrementar();
f.incrementar();
console.log(f.nome, f.contador);
// filha 2

interface ComId {
  id: number;
}

interface ComNome {
  nome: string;
}

interface Ativavel {
  ativo: boolean;
  ativar(): void;
}

class Utilizador implements ComId, ComNome, Ativavel {
  ativo = false;

  constructor(public id: number, public nome: string) {}

  ativar(): void {
    this.ativo = true;
  }
}

const utilizador = new Utilizador(1, "Ana");
utilizador.ativar();
console.log(utilizador.id, utilizador.nome, utilizador.ativo);
// 1 Ana true

abstract class Funcionario {
  constructor(protected nome: string, protected salarioBase: number) {}

  abstract calcularSalario(): number;

  recibo(): string {
    return `${this.nome}: ${this.calcularSalario().toFixed(2)}`;
  }
}

interface Comissionado {
  taxaComissao: number;
  calcularComissao(vendas: number): number;
}

class Vendedor extends Funcionario implements Comissionado {
  taxaComissao = 0.1;

  constructor(nome: string, salarioBase: number, private vendasMes: number) {
    super(nome, salarioBase);
  }

  calcularComissao(vendas: number): number {
    return vendas * this.taxaComissao;
  }

  calcularSalario(): number {
    return this.salarioBase + this.calcularComissao(this.vendasMes);
  }
}

const vendedor = new Vendedor("Rui", 1000, 2000);
console.log(vendedor.recibo());
// Rui: 1200.00

// @ts-expect-error Funcionario continua abstract: não pode ser instanciada mesmo com calcularSalario definido só nas subclasses
const generico = new Funcionario("Anon", 500);

