abstract class Veiculo {
  constructor(protected velocidadeMaxima: number) {}

  abstract consumoMedio(): number;

  descricao(): string {
    return `Velocidade máxima: ${this.velocidadeMaxima} km/h, consumo: ${this.consumoMedio()} l/100km`;
  }
}

class Bicicleta extends Veiculo {
  consumoMedio(): number {
    return 0;
  }
}

const bicicleta = new Bicicleta(25);
console.log(bicicleta.descricao());
// Velocidade máxima: 25 km/h, consumo: 0 l/100km

