// 9.50 EUR

abstract class Funcionario {
  constructor(protected nome: string) {}

  abstract calcularSalario(): number;

  recibo(): string {
    return `${this.nome}: ${this.calcularSalario().toFixed(2)}`;
  }
}

interface Contactavel {
  email: string;
}

interface SujeitoAFerias {
  diasFerias: number;
  marcarFerias(dias: number): void;
}

class Gestor extends Funcionario implements Contactavel, SujeitoAFerias {
  email: string;
  diasFerias = 22;

  constructor(nome: string, email: string, private salarioFixo: number) {
    super(nome);
    this.email = email;
  }

  marcarFerias(dias: number): void {
    this.diasFerias -= dias;
  }

  calcularSalario(): number {
    return this.salarioFixo;
  }
}

const gestor = new Gestor("Marta", "marta@exemplo.pt", 2500);
gestor.marcarFerias(5);
console.log(gestor.recibo(), gestor.diasFerias, gestor.email);
// Marta: 2500.00 17 marta@exemplo.pt

abstract class Repositorio {
  protected itens: string[] = [];

  abstract guardar(item: string): void;
  abstract listar(): string[];

  contar(): number {
    return this.itens.length;
  }
}

interface Auditavel {
  acessos: number;
  registarAcesso(): void;
}

class RepositorioMemoria extends Repositorio implements Auditavel {
  acessos = 0;

  guardar(item: string): void {
    this.itens.push(item);
  }

  listar(): string[] {
    this.registarAcesso();
    return [...this.itens];
  }

  registarAcesso(): void {
    this.acessos++;
  }
}

const repo = new RepositorioMemoria();
repo.guardar("a");
repo.guardar("b");
console.log(repo.listar(), repo.contar(), repo.acessos);
// [ 'a', 'b' ] 2 1

// @ts-expect-error Repositorio é abstract: não pode ser instanciada diretamente
const generico = new Repositorio();

// @ts-expect-error RepositorioIncompleto não implementa o método abstrato listar
class RepositorioIncompleto extends Repositorio {
  guardar(item: string): void {
    this.itens.push(item);
  }
}
